pub fn admit(
    ws_1131: Rc<List<Wt>>,
    c_1132: Cls,
    cap_1133: u64,
    now_1134: u64,
    hs_1135: Rc<List<Hd>>,
    m_1136: u64,
    fx_1137: Rc<List<Fx>>,
    adm_1138: bool,
    room_1139: bool,
) -> Adm {
    match &*ws_1131 {
        List::Nil => {
            return Adm::Adm(hs_1135.clone(), m_1136, Rc::new(List::Nil), fx_1137.clone());
        }
        List::Con(h__, t__) => {
            let head_1223: Wt = h__.clone();
            let tail_1224: Rc<List<Wt>> = t__.clone();
            match &head_1223 {
                Wt::Wt(f0__, f1__, f2__) => {
                    let ticket_1228: u64 = f0__.clone();
                    let cls_1229: Cls = f1__.clone();
                    let share_1230: Shr = f2__.clone();
                    if adm_1138 {
                        if room_1139 {
                            return admit(
                                tail_1224.clone(),
                                c_1132.clone(),
                                cap_1133,
                                now_1134,
                                Rc::new(List::Con(
                                    Hd::Hd(
                                        ticket_1228,
                                        cls_1229.clone(),
                                        share_1230.clone(),
                                        now_1134,
                                    ),
                                    hs_1135.clone(),
                                )),
                                nat_add(m_1136, 1u64),
                                snoc_f(fx_1137.clone(), Fx::FxGrant(ticket_1228)),
                                head_adm(c_1132.clone(), tail_1224.clone()),
                                head_room(
                                    Rc::new(List::Con(
                                        Hd::Hd(
                                            ticket_1228,
                                            cls_1229.clone(),
                                            share_1230.clone(),
                                            now_1134,
                                        ),
                                        hs_1135.clone(),
                                    )),
                                    tail_1224.clone(),
                                    cap_1133,
                                ),
                            );
                        } else {
                            return Adm::Adm(
                                hs_1135.clone(),
                                m_1136,
                                Rc::new(List::Con(
                                    Wt::Wt(ticket_1228, cls_1229.clone(), share_1230.clone()),
                                    tail_1224.clone(),
                                )),
                                fx_1137.clone(),
                            );
                        }
                    } else {
                        return admit_skip(
                            Wt::Wt(ticket_1228, cls_1229.clone(), share_1230.clone()),
                            admit(
                                tail_1224.clone(),
                                c_1132.clone(),
                                cap_1133,
                                now_1134,
                                hs_1135.clone(),
                                m_1136,
                                fx_1137.clone(),
                                head_adm(c_1132.clone(), tail_1224.clone()),
                                head_room(hs_1135.clone(), tail_1224.clone(), cap_1133),
                            ),
                        );
                    }
                }
            }
        }
    }
}

