pub struct Rng(pub u64);
impl Rng {
    pub fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }
}
pub fn gen_Nat(r: &mut Rng, _m: u64) -> u64 {
    r.next() % 3
}
pub fn gen_Bool(r: &mut Rng, _m: u64) -> bool {
    r.next() % 2 == 0
}
pub fn gen_ListNat(r: &mut Rng, m: u64) -> Rc<List<u64>> {
    let k = r.next() % (m + 1);
    let mut xs = Vec::new();
    for _ in 0..k {
        xs.push(gen_Nat(r, 3));
    }
    let mut l: Rc<List<u64>> = Rc::new(List::Nil);
    for x in xs.into_iter().rev() {
        l = Rc::new(List::Con(x, l));
    }
    l
}
